var e={S1:JSON.parse(`{"title":"聆听","heading":"听听麦克风到底发来了什么","goal":"<span class=\\"snd-parts\\"><span class=\\"need\\">KY-037 or INMP441</span></span>两个麦克风，两种接入方式。<b>INMP441</b> 是数字的：自带放大器和 24 位转换器，通过 I2S 传数字。KY-037 有两个输出。<b>AO</b> 是麦克风自身的电压：一个叠在稳定的<i>偏置</i>上的微小波形。<b>DO</b> 是 LM393 比较器给出的“是/否”，由蓝色微调电位器设定。S1 用 ADC 的 DMA 每秒对 AO 采样 16 000 次（不在循环里调用 <code>analogRead()</code>），把它画成示波器，显示它在 ADC 量程中所处的位置，并让你调节电位器。<b>mics</b> 视图把两者并排显示。其他所有声音实验都以它为基础：采样器、4 秒环形缓冲区和电平表都在 <code>kit/lib/sound-kit</code> 中。","goalLine":"把你的声音和拍手声看成波形，比较两个麦克风，读出偏置（或位数），并调节比较器，让它只在大声时触发。","goalCheck":["安静时 <b>scope</b> 显示一条平线，说话时出现波形；吹口哨时波形静止不动（触发已开启）。","<b>bias</b> 视图显示你的模块的偏置（单位 mV），在近距离拍手时没有 CLIPPING；你试过 <code>atten 6</code>，看到步长减半。","在 <b>comparator</b> 视图上，DO 在拍手时亮起，正常说话时保持熄灭：“tuned”。","<code>status</code> 显示 <code>16000 Hz measured</code> 和 <code>DMA overruns 0</code>。","两个麦克风都接上时，<b>mics</b> 视图会告诉你 INMP441 听一个词要清楚多少 dB。"],"learn":["模拟麦克风与数字麦克风","I2S","偏置电压","ADC 衰减","连续 ADC + DMA","环形缓冲区","每位 6 dB，余量 (headroom)","比较器与迟滞","dBFS"],"pins":{"0":{"role":"VCC"},"1":{"role":"MICS +"},"2":{"role":"AO"},"3":{"role":"BLK"},"4":{"role":"RES"},"5":{"role":"DC"},"6":{"role":"CS"},"7":{"role":"SDA"},"8":{"role":"SCL"},"9":{"role":"AMP VIN"},"10":{"role":"GND"},"11":{"role":"BTN"},"12":{"role":"MICS G"},"13":{"role":"SD"},"14":{"role":"WS"},"15":{"role":"SCK"},"16":{"role":"BCLK"},"17":{"role":"LRC"},"18":{"role":"BOOT"},"19":{"role":"DIN"},"20":{"role":"DO"},"21":{"role":"AMP G"}},"wiring":{"title":"接线：麦克风和扬声器（按实验需要接线；屏幕保持与第 03 课相同）","head":["模块引脚","ESP32-S3","说明"],"rows":[["KY-037 + · G","3V3","模拟麦克风。+ 接第二个 3V3 引脚（屏幕用了第一个），G 接 GND。<b>绝不能接 5 V</b>：AO 和 DO 的电压会摆动到模块的供电电压，而 ESP32-S3 的引脚最高只能承受 3.3 V。"],["KY-037 AO","GPIO 6","模拟输出：麦克风的电压。GPIO 6 是 ADC1 通道 5：开启 Wi-Fi 时 ADC1 仍能工作，ADC2 不行。"],["KY-037 DO","GPIO 21","数字输出：当声音比蓝色微调电位器的设定值更响时，LM393 比较器输出高电平。"],["INMP441 VDD · GND","3V3","数字麦克风 (I2S)。VDD 接 3V3（与 KY-037 共用面包板电源轨），GND 接 GND。只能接 3.3 V。"],["INMP441 L/R","GND","低电平 = 它在左声道时隙说话，也就是开发板读取的那一个。"],["INMP441 SCK","GPIO 40","位时钟。由 ESP32 驱动：16 000 × 64 = 1.024 MHz。"],["INMP441 WS","GPIO 41","字选择：左时隙 / 右时隙，每 32 个时钟周期翻转一次。"],["INMP441 SD","GPIO 42","数据，最高有效位在前。已下拉，所以没接麦克风时读到的全是零。"],["MAX98357A VIN · GND","5V","扬声器功放。5V 功率最大（4 Ω 负载约 3 W）；3V3 也能工作，声音小一些。"],["MAX98357A BCLK","GPIO 39","第二个 I2S 端口 (I2S1) 的位时钟；麦克风使用 I2S0，所以两者可以同时工作。"],["MAX98357A LRC","GPIO 38","字选择（左/右）。"],["MAX98357A DIN","GPIO 47","采样数据，16 位。"],["MAX98357A GAIN · SD","不接","两个都悬空：增益 9 dB，播放 (左 + 右) / 2。"],["扬声器 (4 Ω, 3 W)","功放 + / −","接在功放的螺丝端子上：JST-PH2.0 连接线的两根线，红线接 +。"],["屏幕（8 根线）","同第 03 课","保持不变。GPIO 5 上的按钮是可选的：它的作用和 BOOT 一样。"]]},"commands":{"0":{"does":"构建 S1 实验并写入开发板，然后用 <code>uv run pio device monitor</code> 打开监视器。","see":"<code>Listening for an INMP441 on the I2S pins...</code>、<code>Microphone: INMP441 (I2S, digital) (mic setting: auto)</code>（或 KY-037），然后是 <code>Sound lab S1 …</code>、命令列表，以及扬声器发出的三音问候。安静半秒钟：<code>- learning the quiet...</code>","fix":"选错了麦克风：<code>mic inmp441</code> 或 <code>mic ky037</code>（会保存并重启）。没有问候音：扬声器是可选的；检查 VIN 和 DIN。“Failed to connect”：按住 BOOT，点按 RST，松开 BOOT，再运行一次。"},"1":{"does":"shell 使用哪个麦克风。<code>auto</code>（默认）会在启动时用 0.3 秒检测有没有 INMP441。保存在 NVS 中（命名空间 <code>sound</code>）；开发板会重启。","see":"<code>Microphone: INMP441 (I2S, digital) (mic setting: inmp441)</code>；屏幕右上角是一个小小的 <b>D</b>，而不是 DO 指示灯。","fix":"仍然停在 KY-037 上：检查 SCK 40、WS 41、SD 42，L/R 接 GND。"},"2":{"does":"同时打开另一个麦克风并显示两条通道，INMP441 在上：各自在 dBFS 下的安静电平，以及你高出它多少。","see":"<code>INMP441 hears it 12 dB more clearly</code>（这个数字取决于你的房间）；KY-037 的通道颗粒感更重。","fix":"只有一条通道：另一个麦克风没有接线。接好线，然后按 RST：S1 在启动时寻找它。"},"3":{"does":"使用 INMP441 时没有 DO 引脚：开发板用软件做比较。thresh 是高于安静电平的 dB 数（默认 15），带 3 dB 的迟滞。","see":"<code>- software comparator at 20 dB</code>；在 comparator 视图上只有拍手声才会越过它。","fix":""},"4":{"does":"<b>scope</b> 视图绘制最近 20 ms。说话产生一个小小的摆动波形，拍手会填满方框。","see":"粉色的波形；左侧的刻度对说话会增大到 ±1-5 mV，对拍手则是 ±100 mV 甚至更多。","fix":"不管怎么做都是一条平线：AO 没有接在 GPIO 6 上，或者 + 没有接在 3V3 上（模块的电源 LED 必须亮着）。"},"5":{"does":"用数字显示采样器、ADC 和电平。","see":"<code>sampler: 16000 Hz asked, 16000 Hz measured · frames dropped 0 · DMA overruns 0</code>，然后是 <code>ADC: attenuation 12 dB (0-3.1 V) · bias … mV</code>。","fix":"Overruns 不断增加：有东西长时间阻塞了核心 0；把还有什么在运行告诉 Claude。"},"6":{"does":"0-3.3 V 的标尺、你的偏置，以及最近 0.1 秒的摆幅。","see":"偏置线大约在 1-2 V 之间，并有类似 <code>fits in 0-1.75 V: try atten 6 (2x finer)</code> 的提示。","fix":"偏置接近 0 或 3.3 V：模块接在了 5 V 上，或者有导线松了。请使用 3V3。"},"7":{"does":"把 ADC 的量程缩小到 0-1.75 V：每一步从 0.76 mV 变成 0.43 mV。（在 bias 上双击会依次切换 12 → 6 → 2.5 → 0。）","see":"<code>- attenuation 6 dB (0-1.75 V)</code>；在标尺上阴影范围缩小，波形在 scope 上看起来更高。","fix":"<code>CLIPPING</code>：偏置或波形已经放不下了。用 <code>atten 12</code> 回到原来。"},"8":{"does":"打印如何调节比较器，并跳转到 comparator 视图。","see":"三步：安静 → 转动直到 LED2 刚好熄灭；拍手 → 它闪烁；再微调。","fix":""},"9":{"does":"移动比较器的阈值。观察 DO 指示灯（右上角）和曲线条：上面是响度，下面是 DO。","see":"调好了：<code>DO follows the loud moments: tuned</code>，LED2 随拍手闪烁，说话时保持熄灭。","fix":"<code>DO always on</code>：往另一个方向转。哪个方向更灵敏，因厂商而异。"},"10":{"does":"每 50 ms 把电平打印成一根文字条（任何声音实验都有）。<code>plot off</code> 停止。","see":"滚动出现 <code> 23.4 dB |#########          |   | DO 0</code> 这样的行。","fix":""},"11":{"does":"把最新的 64 个采样打印成数字（去掉偏置后的 int16；一个 ADC 步长 = 16）。","see":"四行，每行 16 个用逗号分隔的数字，例如 <code>-32,16,48,…</code>。粘贴到电子表格里并画成折线图。","fix":""},"12":{"does":"Freeze 保持画面不动（在 scope 上双击，或长按）；span 设置屏幕上显示的时间跨度。","see":"<code>scope frozen (freeze again to go on)</code>；设置 <code>span 5</code> 后，口哨的单个波形会变得清晰。","fix":""}},"panels":{"0":{"title":"声音路线，一个实验一个实验地看","intro":"六个实验，各有自己的固件，都读取同一个麦克风。选一个，看看它把声音变成了什么。"},"1":{"title":"从空气到数字","intro":"从你的声音到代码能用的数字之间有八个阶段。逐步查看（或者让它自动播放）；右边的按钮会发出声音，图下方的每个数值都是实时的。"},"2":{"title":"模拟麦克风与数字麦克风：I2S 如何传送一个采样","intro":"KY-037 把一个电压交给 ESP32 去测量；INMP441 自己测量并发送数字。下面是三根线上的一个 I2S 帧。一个时钟周期一个时钟周期地步进，看一个 24 位采样到来，然后变成每个实验都使用的 16 位数字。"},"3":{"title":"波形在 ADC 量程中的位置 (KY-037)","intro":"移动偏置和响度，改变衰减。ADC 只能测量阴影范围之内的信号：超出范围，波形就会被削平（削波，clipping）。只要波形还放得下，量程越小，步长越精细。"},"4":{"title":"比较器和它的电位器","intro":"LM393 把 AO 与电位器设定的电压做比较。在线之上，DO 为高电平（模块上的 LED2 亮起）。拖动虚线（或滑块）并观察 DO：太低它会一直抖动，太高连拍手声都会漏掉。"},"5":{"title":"屏幕上显示什么","intro":"五个视图。单击 = 下一个视图，双击 = 左下角的操作，长按 = 冻结。右上角：电平条、DO 指示灯（使用 INMP441 时是 <b>D</b>）、扬声器播放时的波纹，以及任何录音进行时的红点（S4、S8）。"}},"steps":["接上 KY-037：+ → 3V3（第二个引脚），G → GND，AO → GPIO 6，DO → GPIO 21。屏幕保持与第 03 课相同。模块的电源 LED 亮起。","烧录 <code>sound-lab-s1</code>，打开监视器，安静一秒钟。<b>检查点 1：</b>出现 <code>Mic: AO on GPIO 6 …</code> 这一行，scope 上是一条平线。","在麦克风附近说话、吹口哨和拍手。<b>检查点 2：</b>三种不同的波形；口哨的波形静止不动。","点按切换到 <b>bias</b>，读出你的偏置（mV），试试提示建议的衰减。<b>检查点 3：</b>在 20 cm 外拍手时没有 CLIPPING。","输入 <code>pot</code> 并调节比较器。<b>检查点 4：</b>comparator 视图上显示 “tuned”。","输入 <code>status</code>。<b>检查点 5：</b>16000 Hz measured，0 overruns。"],"note":"使用 INMP441 时，scope 的刻度以满量程的百分比表示，bias 视图变成它 24 位的阶梯（每一位 = 6 dB；声音用了多少位，还剩多少余量），比较器是软件实现的，<b>numbers</b> 还会增加 dB SPL。对 KY-037 的实事求是的预期：它没有放大器。它的 AO 是话筒芯的原始电压，说话只有几毫伏，所以语音只用到 ADC 4096 个台阶中的寥寥几个。这使它成为很好的<b>响度</b>传感器（拍手、敲击、噪声、节拍），但只是一个粗糙的麦克风。DO 只是一个比较器：拍一下手时，波形穿过这条线会在它上面产生几十个边沿，所以各实验监听 AO，把 DO 用于硬件指示灯和作为第二参考。ADC 通过 ADC1 采样，开启 Wi-Fi 时它仍能工作（ADC2 不行）。"}`),S2:{title:`响度`,heading:`你房间的声级计`,goal:`<span class="snd-parts"><span class="need">KY-037 or INMP441</span><span class="opt">MAX98357A + 扬声器（可选）</span></span>有多响？使用 <b>INMP441</b> 时，S2 显示真实的 <b>dB SPL</b>（它的数据手册写着在 94 dB SPL 时为 −26 dBFS，所以 RMS dBFS + 111）：30 是耳语，60 是交谈，85 是听力受损风险线。使用 KY-037 时，它显示高于你房间安静电平的 dB 数。S2 像声级计一样把采样变成分贝：<b>fast</b>（125 ms）或 <b>slow</b>（1 秒）平滑、峰值保持，以及一个会学习你房间的本底噪声。然后它保留一分钟的图表、一份十分钟的噪声日记，以及一个报警器：当声音持续太响时，会点亮第 02 课接在 GPIO 4 上的 LED。`,goalLine:`读出你房间的声级（使用 INMP441 时单位为 dB SPL），看看 fast 和 slow 的区别，记一份日记，并触发（然后消除）报警。`,goalCheck:[`<b>meter</b> 在安静时读数约为 0，说话时为 15-25，拍手为 40+，并大致说明这相当于什么。`,`使用 <code>speed slow</code> 时，数字会平静下来；峰值刻度线仍然能捕捉到拍手声。`,`几分钟之后，<code>diary</code> 会打印带有 low / avg / high 的行。`,`大声放一秒钟音乐会让 <b>alarm</b> 视图变红，点亮 LED，按一下按钮即可消音。`],learn:[`分贝（+6 = ×2）`,`RMS`,`dB SPL 需要已知的灵敏度`,`未加权与 dBA`,`85 dB 风险线`,`快 / 慢平滑`,`本底噪声`,`回声防护`],pins:{0:{role:`VCC`},1:{role:`MICS +`},2:{role:`AO`},3:{role:`BLK`},4:{role:`RES`},5:{role:`DC`},6:{role:`CS`},7:{role:`SDA`},8:{role:`SCL`},9:{role:`AMP VIN`},10:{role:`GND`},11:{role:`BTN`},12:{role:`MICS G`},13:{role:`SD`},14:{role:`WS`},15:{role:`SCK`},16:{role:`BCLK`},17:{role:`LRC`},18:{role:`BOOT`},19:{role:`DIN`},20:{role:`DO`},21:{role:`AMP G`}},wiring:{title:`接线：麦克风和扬声器（按实验需要接线；屏幕保持与第 03 课相同）`,head:[`模块引脚`,`ESP32-S3`,`说明`],rows:[[`KY-037 + · G`,`3V3`,`模拟麦克风。+ 接第二个 3V3 引脚（屏幕用了第一个），G 接 GND。<b>绝不能接 5 V</b>：AO 和 DO 的电压会摆动到模块的供电电压，而 ESP32-S3 的引脚最高只能承受 3.3 V。`],[`KY-037 AO`,`GPIO 6`,`模拟输出：麦克风的电压。GPIO 6 是 ADC1 通道 5：开启 Wi-Fi 时 ADC1 仍能工作，ADC2 不行。`],[`KY-037 DO`,`GPIO 21`,`数字输出：当声音比蓝色微调电位器的设定值更响时，LM393 比较器输出高电平。`],[`INMP441 VDD · GND`,`3V3`,`数字麦克风 (I2S)。VDD 接 3V3（与 KY-037 共用面包板电源轨），GND 接 GND。只能接 3.3 V。`],[`INMP441 L/R`,`GND`,`低电平 = 它在左声道时隙说话，也就是开发板读取的那一个。`],[`INMP441 SCK`,`GPIO 40`,`位时钟。由 ESP32 驱动：16 000 × 64 = 1.024 MHz。`],[`INMP441 WS`,`GPIO 41`,`字选择：左时隙 / 右时隙，每 32 个时钟周期翻转一次。`],[`INMP441 SD`,`GPIO 42`,`数据，最高有效位在前。已下拉，所以没接麦克风时读到的全是零。`],[`MAX98357A VIN · GND`,`5V`,`扬声器功放。5V 功率最大（4 Ω 负载约 3 W）；3V3 也能工作，声音小一些。`],[`MAX98357A BCLK`,`GPIO 39`,`第二个 I2S 端口 (I2S1) 的位时钟；麦克风使用 I2S0，所以两者可以同时工作。`],[`MAX98357A LRC`,`GPIO 38`,`字选择（左/右）。`],[`MAX98357A DIN`,`GPIO 47`,`采样数据，16 位。`],[`MAX98357A GAIN · SD`,`不接`,`两个都悬空：增益 9 dB，播放 (左 + 右) / 2。`],[`扬声器 (4 Ω, 3 W)`,`功放 + / −`,`接在功放的螺丝端子上：JST-PH2.0 连接线的两根线，红线接 +。`],[`屏幕（8 根线）`,`同第 03 课`,`保持不变。GPIO 5 上的按钮是可选的：它的作用和 BOOT 一样。`]]},commands:{0:{does:`构建 S2 实验并写入开发板，然后用 <code>uv run pio device monitor</code> 打开监视器。`,see:`<code>Listening for an INMP441 on the I2S pins...</code>、<code>Microphone: INMP441 (I2S, digital) (mic setting: auto)</code>（或 KY-037），然后是 <code>Sound lab S2 …</code>、命令列表，以及扬声器发出的三音问候。安静半秒钟：<code>- learning the quiet...</code>`,fix:`选错了麦克风：<code>mic inmp441</code> 或 <code>mic ky037</code>（会保存并重启）。没有问候音：扬声器是可选的；检查 VIN 和 DIN。“Failed to connect”：按住 BOOT，点按 RST，松开 BOOT，再运行一次。`},1:{does:`<b>meter</b> 视图：大数字是高于你房间安静电平的 dB 数。`,see:`说话时约 15-25（“talking”），拍手时 40+（“shout, clap, bang”）。白色刻度线是峰值保持。`,fix:`总是 0：安静电平是在你说话时学到的。输入 <code>quiet</code> 并安静半秒钟。`},2:{does:`把电平表、图表和报警切换为 1 秒平滑（在 meter 上双击可切换）。`,see:`<code>- slow: 1 s smoothing</code>；数字变化平缓，拍一下手几乎抬不起它。`,fix:``},3:{does:`在 dB SPL（仅限 INMP441）和高于安静电平的 dB 之间切换。`,see:`<code>- units: dB above the quiet</code>；在 KY-037 上执行 <code>units spl</code>：<code>dB SPL needs the INMP441 (its sensitivity is known)</code>。`,fix:``},4:{does:`报警线：30-120 dB SPL（默认 80），或高于安静电平 3-60 dB（默认 35）。保存在 NVS 中（命名空间 <code>loud</code>）。`,see:`<code>- limit 75 dB SPL</code>；红色虚线会移动。`,fix:``},5:{does:`每次报警时扬声器会播放一次报警曲（按钮也能停止它）。回声防护让 S2 不会测量到自己的曲子。`,see:`<code>- alarm sound off</code>。`,fix:``},6:{does:`超过限值并持续 <code>hold</code>（1 秒）就会触发报警。`,see:`<code>x too loud: 38 dB</code>；<b>alarm</b> 视图红色脉动，GPIO 4 上的 LED 亮起（如果已接线）。`,fix:`没有报警：<code>alarm on</code>，或者把 <code>limit</code> 调低。`},7:{does:`报警响起时，任何按键都能消音；房间平静下来（比报警线低 3 dB）后它会重新待命。`,see:`<code>- alarm silenced</code>，稍后是 <code>+ calm again</code>。`,fix:``},8:{does:`打印最近十分钟，每 10 秒一行：最安静、平均、最响，以及 ALARM。`,see:`<code>  60s     2   11   34  |=====      |</code> 这样的行。`,fix:`是空的：日记每 10 秒填一行。几分钟后再回来看。`}},panels:{0:{title:`分贝是什么`,intro:`我们的耳朵听的是比值，而不是差值，所以响度用分贝来衡量：20 × log10（当前值 ÷ 安静值）。拖动响度并观察波形：每 +6 dB 高度加倍，+20 dB 是十倍。`},1:{title:`Fast、slow 和本底`,intro:`同一个声音通过电平表的三种“镜头”重放。选一个场景。本底跟随安静电平：它会立刻下降，并每秒爬升 0.5 dB，所以一直转着的风扇会变成新的“安静”。`},2:{title:`屏幕上显示什么`,intro:`四个视图。单击 = 下一个，双击 = 左下角的操作（speed、quiet、diary、alarm），长按 = 重新学习安静电平。报警响起时，任何按键都能消音。`}},steps:[`接线与 S1 相同。可选：第 02 课的 LED 通过它的电阻接在 GPIO 4 上（报警灯）。`,`烧录 <code>sound-lab-s2</code> 并安静一秒钟。<b>检查点 1：</b>电平表读数为 0-3 dB，“quiet”。`,`在 30 cm 外用正常音量说话。<b>检查点 2：</b>15-25 dB，“talking”。`,`<code>speed slow</code>，然后 <code>speed fast</code>。<b>检查点 3：</b>你能描述两者的差别。`,`在麦克风附近大声播放音乐。<b>检查点 4：</b>alarm 视图显示 TOO LOUD，然后用按钮消音。`,`放着不管十分钟，然后运行 <code>diary</code>。<b>检查点 5：</b>一张记录你房间这十分钟的表。`],note:`dB SPL 需要一个灵敏度已知的麦克风：INMP441 的灵敏度写在它的数据手册里，所以 S2 能显示它（未加权，误差约 ±2 dB；真正的声级计常显示 dBA，它像耳朵一样对频率加权，对低沉的嗡嗡声读数更低）。KY-037 的数字是高于<i>你</i>房间安静电平的 dB 数，而不是 dB SPL（校准过的声级计显示的数字）：那需要一个参考麦克风和话筒芯的灵敏度。本底是在开机后或 <code>quiet</code> 之后的前半秒学到的，然后跟随安静电平（立刻下降，每秒上升 0.5 dB）。设置（speed、limit、hold、alarm）在复位后保存在 NVS 中；日记则不会。`},S3:{title:`拍手控制`,heading:`用你的双手来切换设备`,goal:`<span class="snd-parts"><span class="need">KY-037 or INMP441</span><span class="opt">MAX98357A + 扬声器（可选）</span></span>拍一下手切换 LED，拍两下改变 RGB 颜色，拍三下让屏幕休眠，拍四下开派对。说话、口哨或音乐都不算：拍手不只是响，它还有一个<b>形状</b>（4 ms 内的跳变，160 ms 内结束）。靠得很近的拍手组成一个模式；停顿 0.65 秒结束这个模式。每个模式做什么，是一份保存在 NVS 里、你可以修改的映射表，每个动作还会用扬声器上自己的小声音来回应。`,goalLine:`让拍 1、2、3、4 下分别做四件不同的事，证明说话不会触发它们，并根据你自己的拍手来调节检测器。`,goalCheck:[`拍一下手切换 GPIO 4 上的 LED（或者打印 <code>LED on</code>），拍两下改变 RGB 颜色。`,`在 <b>timeline</b> 上，拍手会得到一面青色小旗，说出的一个词是一根琥珀色的 <i>long</i> 条，什么也不会发生。`,`<code>learn</code> + 拍 5 下手，会根据你最轻的那一下设置 <code>sens</code>。`,`你用 <code>map</code> 重新映射了一个模式，并且它在复位后仍然保留。`],learn:[`起始点检测`,`拍手的形状`,`迟滞`,`按时间分组`,`根据数据校准`,`NVS 映射表`,`用声音作反馈`,`回声防护`],pins:{0:{role:`VCC`},1:{role:`MICS +`},2:{role:`AO`},3:{role:`BLK`},4:{role:`RES`},5:{role:`DC`},6:{role:`CS`},7:{role:`SDA`},8:{role:`SCL`},9:{role:`AMP VIN`},10:{role:`GND`},11:{role:`BTN`},12:{role:`MICS G`},13:{role:`SD`},14:{role:`WS`},15:{role:`SCK`},16:{role:`BCLK`},17:{role:`LRC`},18:{role:`BOOT`},19:{role:`DIN`},20:{role:`DO`},21:{role:`AMP G`}},wiring:{title:`接线：麦克风和扬声器（按实验需要接线；屏幕保持与第 03 课相同）`,head:[`模块引脚`,`ESP32-S3`,`说明`],rows:[[`KY-037 + · G`,`3V3`,`模拟麦克风。+ 接第二个 3V3 引脚（屏幕用了第一个），G 接 GND。<b>绝不能接 5 V</b>：AO 和 DO 的电压会摆动到模块的供电电压，而 ESP32-S3 的引脚最高只能承受 3.3 V。`],[`KY-037 AO`,`GPIO 6`,`模拟输出：麦克风的电压。GPIO 6 是 ADC1 通道 5：开启 Wi-Fi 时 ADC1 仍能工作，ADC2 不行。`],[`KY-037 DO`,`GPIO 21`,`数字输出：当声音比蓝色微调电位器的设定值更响时，LM393 比较器输出高电平。`],[`INMP441 VDD · GND`,`3V3`,`数字麦克风 (I2S)。VDD 接 3V3（与 KY-037 共用面包板电源轨），GND 接 GND。只能接 3.3 V。`],[`INMP441 L/R`,`GND`,`低电平 = 它在左声道时隙说话，也就是开发板读取的那一个。`],[`INMP441 SCK`,`GPIO 40`,`位时钟。由 ESP32 驱动：16 000 × 64 = 1.024 MHz。`],[`INMP441 WS`,`GPIO 41`,`字选择：左时隙 / 右时隙，每 32 个时钟周期翻转一次。`],[`INMP441 SD`,`GPIO 42`,`数据，最高有效位在前。已下拉，所以没接麦克风时读到的全是零。`],[`MAX98357A VIN · GND`,`5V`,`扬声器功放。5V 功率最大（4 Ω 负载约 3 W）；3V3 也能工作，声音小一些。`],[`MAX98357A BCLK`,`GPIO 39`,`第二个 I2S 端口 (I2S1) 的位时钟；麦克风使用 I2S0，所以两者可以同时工作。`],[`MAX98357A LRC`,`GPIO 38`,`字选择（左/右）。`],[`MAX98357A DIN`,`GPIO 47`,`采样数据，16 位。`],[`MAX98357A GAIN · SD`,`不接`,`两个都悬空：增益 9 dB，播放 (左 + 右) / 2。`],[`扬声器 (4 Ω, 3 W)`,`功放 + / −`,`接在功放的螺丝端子上：JST-PH2.0 连接线的两根线，红线接 +。`],[`屏幕（8 根线）`,`同第 03 课`,`保持不变。GPIO 5 上的按钮是可选的：它的作用和 BOOT 一样。`]]},commands:{0:{does:`构建 S3 实验并写入开发板，然后用 <code>uv run pio device monitor</code> 打开监视器。`,see:`<code>Listening for an INMP441 on the I2S pins...</code>、<code>Microphone: INMP441 (I2S, digital) (mic setting: auto)</code>（或 KY-037），然后是 <code>Sound lab S3 …</code>、命令列表，以及扬声器发出的三音问候。安静半秒钟：<code>- learning the quiet...</code>`,fix:`选错了麦克风：<code>mic inmp441</code> 或 <code>mic ky037</code>（会保存并重启）。没有问候音：扬声器是可选的；检查 VIN 和 DIN。“Failed to connect”：按住 BOOT，点按 RST，松开 BOOT，再运行一次。`},1:{does:`拍一下 = <code>led</code>，两下 = <code>colour</code>（默认设置；三下 = <code>screen</code>，四下 = <code>party</code>）。`,see:`<code>- 1 clap -> led</code>、<code>+ LED on</code>；然后 <code>- 2 claps -> colour</code>、<code>+ colour: warm white</code>。<b>lamp</b> 视图两者都会显示。`,fix:`没反应：拍得太轻，达不到 <code>sens</code> 18 dB。试试 <code>learn</code>。`},2:{does:`实时打印每一次拍手、长声音和分组。`,see:`<code>  clap at 5120 ms: 31.0 dB, 48 ms long</code>、<code>  LONG (not a clap) at …: 22.0 dB, 380 ms long</code>、<code>  group of 2: gaps 290 ms</code>。`,fix:`用 <code>test off</code> 停止。`},3:{does:`跳转到 <b>tune</b>：像平时那样拍 5 下手。sens 会设为最轻那一下的 60 %（在 8 到 40 dB 之间），并保存。`,see:`<code>- clap 1 of 5: 29 dB</code> … <code>+ learnt: sens 17 dB (saved)</code>；五根条，带有各自的 dB 和 ms。`,fix:`在 learn 期间说话，会被计入 <i>long (voice?)</i>，而不是拍手。`},4:{does:`现在拍三下手会在扬声器上播放 twinkle。可用的动作：led colour dark screen view party tune none。`,see:`<code>+ 3 claps -> tune (saved)</code>；<code>maps</code> 会打印全部四个映射。`,fix:``},5:{does:`每个动作都会用声音回应：LED 的升/降音、颜色琶音、screen 和 view 的咔哒声、派对的号角、模式没有映射时的低沉 No。<code>sound off</code> 会让它们静音（会保存）。`,see:`<code>+ pattern sounds off (saved)</code>。`,fix:``},6:{does:`更短的停顿就结束一个模式：更干脆，但拍得慢的人会被拆成两个模式。`,see:`<code>+ pause 400 ms ends a pattern (saved)</code>。`,fix:``},7:{does:`不用拍手就运行一个动作（用来测试接线）。`,see:`<code>+ party!</code>，RGB LED 上有 2 秒彩虹。`,fix:``}},panels:{0:{title:`这是拍手吗？检测器，每次 4 ms`,intro:`与 kit/lib/sound-kit/src/onsets.h 相同的规则，运行在你选的一段声音上。一次一帧地步进，或者播放，移动上升线和释放线。待命 → 响 (ONSET) → 安静（如果很短就是 CLAP，否则是 LONG）→ 安静 40 ms 后再次待命。`},1:{title:`屏幕上显示什么`,intro:`四个视图。单击 = 下一个，双击 = 左下角的操作（test、colour、maps、learn），长按 = learn。`}},steps:[`接线与 S1 相同。可选：第 02 课的 LED 接在 GPIO 4 上。`,`烧录 <code>sound-lab-s3</code>，安静一秒钟。<b>检查点 1：</b><b>timeline</b> 显示一条带有上升线和释放线的平线。`,`拍一下，再拍两下。<b>检查点 2：</b>LED 切换，RGB 变色。`,`在麦克风旁边正常说话。<b>检查点 3：</b>琥珀色的 <i>long</i> 条，没有动作。`,`<code>learn</code>，拍 5 下手。<b>检查点 4：</b>一个新的 <code>sens</code>，已保存。`,`<code>map 1 party</code>，拍一下手，复位开发板，再拍一下手。<b>检查点 5：</b>仍然是派对。`],note:`开发板自己发出的声音永远不会被算作拍手：扬声器播放期间（以及之后 200 ms），检测器收不到任何帧，这就是回声防护。连续五下或更多拍手算作鼓掌，什么也不做。拍三下手会熄灭背光：30 秒后或按任意按键就会恢复，所以屏幕不会“丢”。检测器通过电平表监听 AO，而不是 DO：一次拍手会在 DO 上产生几十个边沿。`},S4:{title:`录音机`,heading:`一台声控录音机`,goal:`<span class="snd-parts"><span class="need">KY-037 or INMP441</span><span class="opt">Wi-Fi (W1)（可选）</span><span class="opt">MAX98357A + 扬声器（可选）</span></span>处于待命状态时，开发板等待比触发电平更响的声音，然后录入 PSRAM，从触发<i>之前</i>半秒开始（环形缓冲区里还有它），直到出现 1.2 秒的安静。最多 12 段录音，共 6 MB，复位后消失。你可以在手机上通过 <code>http://bench.local</code> 收听（需要 W1 保存的 Wi-Fi 网络，再加管理员令牌），也可以用 <code>tools/sound_pull.py</code> 通过 USB 拉取 WAV，或者在开发板自己的扬声器上播放（<code>play 3 0.7</code>：更慢更低沉）。录音时，不管是谁启动的，开发板总会显示 REC 并亮起红色 LED。`,goalLine:`免提录下一句话，看看预录音，在手机上播放，并把一段录音作为 WAV 文件拉取到你的 Mac。`,goalCheck:[`<code>arm</code>，然后说话：<b>recorder</b> 视图从 ARMED → REC → ARMED，<code>clips</code> 列出一段语音录音。`,`摔门声或一下拍手会启动录音，但会被丢弃（太短）。`,`<code>http://bench.local</code> 上的手机页面用令牌解锁，画出录音波形并播放它。`,`<code>tools/sound_pull.py</code> 写出了一个能在 Mac 上播放的 .wav。`,`<code>play</code>（或在 <b>clips</b> 上双击）会在开发板的扬声器上播放选中的录音；<code>play 1 2</code> 是花栗鼠的声音。`],learn:[`来自环形缓冲区的预录音`,`触发 + 保持`,`PSRAM 录音存储`,`WAV 格式`,`流式响应`,`base64 + CRC-32`,`播放速度 = 音高`,`令牌与可见的录音状态`],pins:{0:{role:`VCC`},1:{role:`MICS +`},2:{role:`AO`},3:{role:`BLK`},4:{role:`RES`},5:{role:`DC`},6:{role:`CS`},7:{role:`SDA`},8:{role:`SCL`},9:{role:`AMP VIN`},10:{role:`GND`},11:{role:`BTN`},12:{role:`MICS G`},13:{role:`SD`},14:{role:`WS`},15:{role:`SCK`},16:{role:`BCLK`},17:{role:`LRC`},18:{role:`BOOT`},19:{role:`DIN`},20:{role:`DO`},21:{role:`AMP G`}},wiring:{title:`接线：麦克风和扬声器（按实验需要接线；屏幕保持与第 03 课相同）`,head:[`模块引脚`,`ESP32-S3`,`说明`],rows:[[`KY-037 + · G`,`3V3`,`模拟麦克风。+ 接第二个 3V3 引脚（屏幕用了第一个），G 接 GND。<b>绝不能接 5 V</b>：AO 和 DO 的电压会摆动到模块的供电电压，而 ESP32-S3 的引脚最高只能承受 3.3 V。`],[`KY-037 AO`,`GPIO 6`,`模拟输出：麦克风的电压。GPIO 6 是 ADC1 通道 5：开启 Wi-Fi 时 ADC1 仍能工作，ADC2 不行。`],[`KY-037 DO`,`GPIO 21`,`数字输出：当声音比蓝色微调电位器的设定值更响时，LM393 比较器输出高电平。`],[`INMP441 VDD · GND`,`3V3`,`数字麦克风 (I2S)。VDD 接 3V3（与 KY-037 共用面包板电源轨），GND 接 GND。只能接 3.3 V。`],[`INMP441 L/R`,`GND`,`低电平 = 它在左声道时隙说话，也就是开发板读取的那一个。`],[`INMP441 SCK`,`GPIO 40`,`位时钟。由 ESP32 驱动：16 000 × 64 = 1.024 MHz。`],[`INMP441 WS`,`GPIO 41`,`字选择：左时隙 / 右时隙，每 32 个时钟周期翻转一次。`],[`INMP441 SD`,`GPIO 42`,`数据，最高有效位在前。已下拉，所以没接麦克风时读到的全是零。`],[`MAX98357A VIN · GND`,`5V`,`扬声器功放。5V 功率最大（4 Ω 负载约 3 W）；3V3 也能工作，声音小一些。`],[`MAX98357A BCLK`,`GPIO 39`,`第二个 I2S 端口 (I2S1) 的位时钟；麦克风使用 I2S0，所以两者可以同时工作。`],[`MAX98357A LRC`,`GPIO 38`,`字选择（左/右）。`],[`MAX98357A DIN`,`GPIO 47`,`采样数据，16 位。`],[`MAX98357A GAIN · SD`,`不接`,`两个都悬空：增益 9 dB，播放 (左 + 右) / 2。`],[`扬声器 (4 Ω, 3 W)`,`功放 + / −`,`接在功放的螺丝端子上：JST-PH2.0 连接线的两根线，红线接 +。`],[`屏幕（8 根线）`,`同第 03 课`,`保持不变。GPIO 5 上的按钮是可选的：它的作用和 BOOT 一样。`]]},commands:{0:{does:`构建 S4 实验并写入开发板，然后用 <code>uv run pio device monitor</code> 打开监视器。`,see:`<code>Listening for an INMP441 on the I2S pins...</code>、<code>Microphone: INMP441 (I2S, digital) (mic setting: auto)</code>（或 KY-037），然后是 <code>Sound lab S4 …</code>、命令列表，以及扬声器发出的三音问候。安静半秒钟：<code>- learning the quiet...</code>`,fix:`选错了麦克风：<code>mic inmp441</code> 或 <code>mic ky037</code>（会保存并重启）。没有问候音：扬声器是可选的；检查 VIN 和 DIN。“Failed to connect”：按住 BOOT，点按 RST，松开 BOOT，再运行一次。`},1:{does:`声控：比 <code>trigger</code>（高于安静电平 15 dB）更响就会开始一段录音。`,see:`<code>- armed: talk and it records</code>；<b>recorder</b> 视图显示 ARMED（青色圆环）。`,fix:``},2:{does:`从你说第一个字之前半秒开始录，直到最后一次大声之后 1.2 秒。`,see:`<code>x REC clip 1 (voice)</code>；红色的 REC 2.4 s，标题栏的红点，RGB LED 变红；然后是 <code>+ clip 1: 3.1 s</code>。`,fix:`一直不启动：靠近一点说话，或者 <code>trigger 10</code>。`},3:{does:`以 0.7 倍速在开发板的扬声器上播放第 1 段录音（更低沉、更慢）。不带数字时：播放在 <b>clips</b> 视图上选中的那一段。音量会像下载时一样放大，但最多 ×16。<code>stop</code> 会停止播放；<code>rec</code> 会在录音前停止播放；录音期间会被拒绝。`,see:`<code>+ playing clip 1 (4.4 s) at x0.70</code>，然后 <code>- clip 1 played</code>；标题栏出现波纹。`,fix:`<code>recording: stop first (the microphone would hear the speaker)</code>。`},4:{does:`列出各段录音：编号、时长、语音还是手动、最响电平、发送时放大了多少、时间。`,see:`<code>    1    3.1s  voice  -38.2 dBFS  x23.4  2026-10-14 14:02:31</code>`,fix:``},5:{does:`打印手机页面所要求的管理员令牌（与 W2/R7/R8 共用）。`,see:`<code>Admin token: 3f…</code> 以及该把它粘贴到哪里。`,fix:`不要把它发到聊天里，也不要提交到 git；<code>token new</code> 会替换它。`},6:{does:`开发板自己的页面：实时电平、arm / rec / stop、带有每段波形的录音列表、播放和下载、速度选项，以及每段录音的 <b>Play on board</b> / <b>Stop on board</b>。令牌只保留在那个标签页里。`,see:`一张带有波形的录音卡片；播放时播放头会移动。`,fix:`“no Wi-Fi saved”：先烧录 wifi-lab-w1 并连接一次。页面打不开？是同一个网络吗？试试 <code>wifi</code> 显示的 IP。`},7:{does:`先关掉监视器。输入 <code>send 1</code>，读取 base64 的 WAV，检查 CRC-32 和大小，写出文件。`,see:`<code>Receiving clip 1: 99244 bytes as …</code>，然后是 <code>Saved … (3.1 s at 16000 Hz, 99244 bytes, CRC ok)</code>。`,fix:`<code>Could not open … (is the serial monitor still open?)</code>：把它关掉。`}},panels:{0:{title:`声控录音，一步步走一遍`,intro:`九秒钟：一声关门的砰响，然后是一句中间有停顿的话。逐步查看或播放，移动触发电平和保持时间。琥珀色 = 从环形缓冲区取来的预录音，红色 = 已录制，灰色 = 被丢弃。`},1:{title:`把音频取出来`,intro:`三条路径：通过 Wi-Fi 到手机，通过 USB 串口到 Mac，或者用开发板自己的扬声器。下面是每个 WAV 文件开头的 44 个字节（以 16 000 Hz 的 3.2 秒录音为例）。`},2:{title:`屏幕上显示什么`,intro:`三个视图。单击 = 下一个，双击 = 左下角的操作（arm、next、wifi），长按 = rec / stop。`}},steps:[`接线与 S1 相同。开发板需要保存好 W1 的 Wi-Fi 网络（仅手机页面需要）。`,`烧录 <code>sound-lab-s4</code>。<b>检查点 1：</b>recorder 视图上显示 OFF，Wi-Fi 连上后出现 <code>page: http://bench.local</code>。`,`<code>arm</code>，说一句话。<b>检查点 2：</b>一段录音；你说第一个字之前有琥珀色的预录音。`,`拍一下手。<b>检查点 3：</b><code>a bang, not a voice: clip 2 dropped</code>。`,`在手机上打开页面，粘贴 <code>token</code>。<b>检查点 4：</b>你的录音播放出来了。`,`关掉监视器，运行 <code>tools/sound_pull.py</code>。<b>检查点 5：</b>你的 Mac 上有了一个 .wav。`],note:`隐私是内置的，不是可选的：不管是谁启动的，录音时开发板上总会显示（REC、红点、红色 LED）；页面上的每一条音频途径都需要管理员令牌；录音只存在 RAM 里，复位后就消失。声音会比较单薄、带嘶嘶声：录音在输出时会被归一化（放大最多 64 倍），这会把嘶嘶声和人声一起抬高。这个模块首先是一个响度传感器，其次才是麦克风。`},S5:{title:`频谱`,heading:`看看一个声音里有哪些频率`,goal:`<span class="snd-parts"><span class="need">KY-037 or INMP441</span><span class="opt">MAX98357A + 扬声器（可选）</span></span>我们自己写的 FFT（不用库）每秒约 25 次对最新的 512 个采样做运算：从 100 Hz 到 8 kHz 的柱状图、一个滚动的瀑布图、一个能说出你吹口哨或哼唱的音名的调音器，以及一个用口哨音高来操控的游戏。有了扬声器，开发板还能自检：<code>ref</code> 为调音器播放一个参考音，<code>sweep</code> 让音调从 100 Hz 爬升到 8 kHz，掠过各根柱子。`,goalLine:`找出你的口哨的频率，看看为什么更细的频率格更慢，并在 steer 游戏中得分。`,goalCheck:[`吹口哨时 <b>bars</b> 视图显示一根高高的柱子，说话时则是许多矮柱子。`,`<b>tuner</b> 说出你的音名，指针在 ±5 音分以内变成青色。`,`<code>fft 1024</code> 和 <code>fft 256</code>：你能说出变了什么（每格多少 Hz，反应有多快）。`,`<b>steer</b>：你至少打中了 3 个目标。`],learn:[`FFT 频率格 (bin)`,`汉宁窗与频谱泄漏`,`奈奎斯特频率 (8 kHz)`,`分辨率与速度`,`对数频率`,`音名与音分`,`参考音`,`对数扫频`],pins:{0:{role:`VCC`},1:{role:`MICS +`},2:{role:`AO`},3:{role:`BLK`},4:{role:`RES`},5:{role:`DC`},6:{role:`CS`},7:{role:`SDA`},8:{role:`SCL`},9:{role:`AMP VIN`},10:{role:`GND`},11:{role:`BTN`},12:{role:`MICS G`},13:{role:`SD`},14:{role:`WS`},15:{role:`SCK`},16:{role:`BCLK`},17:{role:`LRC`},18:{role:`BOOT`},19:{role:`DIN`},20:{role:`DO`},21:{role:`AMP G`}},wiring:{title:`接线：麦克风和扬声器（按实验需要接线；屏幕保持与第 03 课相同）`,head:[`模块引脚`,`ESP32-S3`,`说明`],rows:[[`KY-037 + · G`,`3V3`,`模拟麦克风。+ 接第二个 3V3 引脚（屏幕用了第一个），G 接 GND。<b>绝不能接 5 V</b>：AO 和 DO 的电压会摆动到模块的供电电压，而 ESP32-S3 的引脚最高只能承受 3.3 V。`],[`KY-037 AO`,`GPIO 6`,`模拟输出：麦克风的电压。GPIO 6 是 ADC1 通道 5：开启 Wi-Fi 时 ADC1 仍能工作，ADC2 不行。`],[`KY-037 DO`,`GPIO 21`,`数字输出：当声音比蓝色微调电位器的设定值更响时，LM393 比较器输出高电平。`],[`INMP441 VDD · GND`,`3V3`,`数字麦克风 (I2S)。VDD 接 3V3（与 KY-037 共用面包板电源轨），GND 接 GND。只能接 3.3 V。`],[`INMP441 L/R`,`GND`,`低电平 = 它在左声道时隙说话，也就是开发板读取的那一个。`],[`INMP441 SCK`,`GPIO 40`,`位时钟。由 ESP32 驱动：16 000 × 64 = 1.024 MHz。`],[`INMP441 WS`,`GPIO 41`,`字选择：左时隙 / 右时隙，每 32 个时钟周期翻转一次。`],[`INMP441 SD`,`GPIO 42`,`数据，最高有效位在前。已下拉，所以没接麦克风时读到的全是零。`],[`MAX98357A VIN · GND`,`5V`,`扬声器功放。5V 功率最大（4 Ω 负载约 3 W）；3V3 也能工作，声音小一些。`],[`MAX98357A BCLK`,`GPIO 39`,`第二个 I2S 端口 (I2S1) 的位时钟；麦克风使用 I2S0，所以两者可以同时工作。`],[`MAX98357A LRC`,`GPIO 38`,`字选择（左/右）。`],[`MAX98357A DIN`,`GPIO 47`,`采样数据，16 位。`],[`MAX98357A GAIN · SD`,`不接`,`两个都悬空：增益 9 dB，播放 (左 + 右) / 2。`],[`扬声器 (4 Ω, 3 W)`,`功放 + / −`,`接在功放的螺丝端子上：JST-PH2.0 连接线的两根线，红线接 +。`],[`屏幕（8 根线）`,`同第 03 课`,`保持不变。GPIO 5 上的按钮是可选的：它的作用和 BOOT 一样。`]]},commands:{0:{does:`构建 S5 实验并写入开发板，然后用 <code>uv run pio device monitor</code> 打开监视器。`,see:`<code>Listening for an INMP441 on the I2S pins...</code>、<code>Microphone: INMP441 (I2S, digital) (mic setting: auto)</code>（或 KY-037），然后是 <code>Sound lab S5 …</code>、命令列表，以及扬声器发出的三音问候。安静半秒钟：<code>- learning the quiet...</code>`,fix:`选错了麦克风：<code>mic inmp441</code> 或 <code>mic ky037</code>（会保存并重启）。没有问候音：扬声器是可选的；检查 VIN 和 DIN。“Failed to connect”：按住 BOOT，点按 RST，松开 BOOT，再运行一次。`},1:{does:`<b>bars</b> 视图：口哨是一根高柱子（1-3 kHz），哼唱则更低更宽。`,see:`顶部是 <code>loudest 1.76 kHz (A6)</code>；右侧：<code>N 512 - 31 Hz/bin - … us</code>。`,fix:`没有任何动静：在一只手掌的距离内吹口哨（模块上没有放大器）。`},2:{does:`打印 5 个最强的频率及其音名。`,see:`<code>   1765.6 Hz   -31.2 dBFS  A6   +2 cents</code> …`,fix:``},3:{does:`采样数量翻倍：频率格相隔 15.6 Hz，但每个答案要看 64 ms。<code>fft 256</code>：62.5 Hz 的频率格，16 ms。`,see:`<code>- FFT 1024: 15.6 Hz per bin, 64 ms window</code>。`,fix:``},4:{does:`扬声器播放 1 秒的正弦波：取你最近 2 秒内吹出的音最接近的音名，否则是 A4。S5 直接读取环形缓冲区，所以它是有意听到自己的音。在 <b>tuner</b> 上双击效果相同。`,see:`<code>- reference A4 = 440.0 Hz, 1 s</code>；调音器显示 A4，指针接近 0。`,fix:`偏差很多音分：扬声器和麦克风没问题；检查 <code>a4</code>。`},5:{does:`一个 4 秒的音，按对数刻度从 100 Hz 扫到 8 kHz；屏幕跳转到瀑布图。`,see:`瀑布图上出现一条以均匀斜率向上爬升的斜线：对数频率，和柱状图一样。`,fix:``},6:{does:`把音名调整为 A4 = 442 Hz（有些乐团这样做）。`,see:`<code>- A4 = 442.0 Hz</code>；调音器的音分偏移约 8。`,fix:``},7:{does:`圆点在对数刻度（600-2500 Hz）上跟随你的音高；把它保持在圆环里 1 秒就得分。RGB LED 会采用圆点的颜色。`,see:`<code>+ target 1!</code>，别处出现一个新的圆环。`,fix:`够不到顶部：<code>range 500 2000</code>。`},8:{does:`这个 FFT 能看到什么、看不到什么。`,see:`最高到 8000 Hz（奈奎斯特），频率格相隔 31.2 Hz，每个答案 32 ms，以及“没有放大器”的警告。`,fix:``}},panels:{0:{title:`构建一个声音，查看它的频谱`,intro:`最多三个音加噪声，上面是采样，下面是 FFT 的各个频率格。取消勾选窗函数可以看到频谱泄漏；改变 N，用更锐利的频率格换取更慢的响应。`},1:{title:`从一声口哨到一个音名`,intro:`六个步骤，和 tuner 视图每秒做 25 次的一样。移动口哨滑块，看抛物线如何在两个频率格之间找到音高。`},2:{title:`屏幕上显示什么`,intro:`四个视图。单击 = 下一个，双击 = 左下角的操作（hold、hold、peaks、target），长按 = hold。`}},steps:[`接线与 S1 相同。`,`烧录 <code>sound-lab-s5</code>。<b>检查点 1：</b>启动时打印出的各项限制。`,`在 <b>bars</b> 上吹一个稳定的音，然后切换到 <b>waterfall</b>。<b>检查点 2：</b>瀑布图上有一条明亮的线。`,`<b>tuner</b>：吹口哨直到指针变成青色。<b>检查点 3：</b>一个你能重复的音名。`,`<code>fft 256</code>、<code>fft 1024</code>，再回到 <code>fft 512</code>。<b>检查点 4：</b>你看到了其中的取舍。`,`<b>steer</b>：得 3 分。<b>检查点 5：</b><code>target 3!</code>。`],note:`值得了解的限制：在每秒 16 000 个采样时，高于 8 kHz 的任何声音都看不到（奈奎斯特），更高的声音会折叠回来，变成假信号。每个频段都会学习自己的安静电平（风扇嗡嗡声偏低，笔记本电脑的啸叫偏高），所以视图显示的是高于各频段本底的 dB 数。语音有许多谐波，没有单一清晰的峰，这就是调音器要求清晰度 ≥ 12 dB 的原因：吹口哨或哼唱。`},S6:{title:`声音游戏`,heading:`玩玩麦克风听到的声音`,goal:`<span class="snd-parts"><span class="need">KY-037 or INMP441</span><span class="opt">MAX98357A + 扬声器（可选）</span></span>一个麦克风上的三个游戏，每个游戏只在它的视图显示在屏幕上时才监听。<b>knock</b>：一把敲击锁，用你的秘密节奏打开，快慢皆可。<b>bird</b>：Clap Bird，每拍一下手就是扇一下翅膀。<b>party</b>：开发板在音乐中找到节拍，并向它抛出灯光。有了扬声器：Clap Bird 里有哔声、叮声和撞击声，还能回放秘密敲击，以及一段解锁曲。`,goalLine:`用你的秘密敲击打开锁（并用错误的节奏失败一次），在 Clap Bird 里通过 5 根管子，并让 party 跟上一首歌的节奏。`,goalCheck:[`<code>knock set</code> + 一段节奏就保存了一个秘密；同样的节奏慢一点仍然能打开（GPIO 4 上的 LED，RGB 绿色 5 秒）。`,`不同的节奏会让挂锁晃动：<code>locked: the rhythm is off</code>。`,`Clap Bird：得分 5 或更高，并且 <code>best</code> 在复位后仍然保留。`,`<b>party</b> 显示一个接近歌曲速度的 BPM。`],learn:[`与速度无关的节奏`,`容差`,`固定步长的游戏物理`,`延迟（起始点与拍手）`,`节拍检测`,`中位数速度`,`一个传感器，多种用途`],pins:{0:{role:`VCC`},1:{role:`MICS +`},2:{role:`AO`},3:{role:`BLK`},4:{role:`RES`},5:{role:`DC`},6:{role:`CS`},7:{role:`SDA`},8:{role:`SCL`},9:{role:`AMP VIN`},10:{role:`GND`},11:{role:`BTN`},12:{role:`MICS G`},13:{role:`SD`},14:{role:`WS`},15:{role:`SCK`},16:{role:`BCLK`},17:{role:`LRC`},18:{role:`BOOT`},19:{role:`DIN`},20:{role:`DO`},21:{role:`AMP G`}},wiring:{title:`接线：麦克风和扬声器（按实验需要接线；屏幕保持与第 03 课相同）`,head:[`模块引脚`,`ESP32-S3`,`说明`],rows:[[`KY-037 + · G`,`3V3`,`模拟麦克风。+ 接第二个 3V3 引脚（屏幕用了第一个），G 接 GND。<b>绝不能接 5 V</b>：AO 和 DO 的电压会摆动到模块的供电电压，而 ESP32-S3 的引脚最高只能承受 3.3 V。`],[`KY-037 AO`,`GPIO 6`,`模拟输出：麦克风的电压。GPIO 6 是 ADC1 通道 5：开启 Wi-Fi 时 ADC1 仍能工作，ADC2 不行。`],[`KY-037 DO`,`GPIO 21`,`数字输出：当声音比蓝色微调电位器的设定值更响时，LM393 比较器输出高电平。`],[`INMP441 VDD · GND`,`3V3`,`数字麦克风 (I2S)。VDD 接 3V3（与 KY-037 共用面包板电源轨），GND 接 GND。只能接 3.3 V。`],[`INMP441 L/R`,`GND`,`低电平 = 它在左声道时隙说话，也就是开发板读取的那一个。`],[`INMP441 SCK`,`GPIO 40`,`位时钟。由 ESP32 驱动：16 000 × 64 = 1.024 MHz。`],[`INMP441 WS`,`GPIO 41`,`字选择：左时隙 / 右时隙，每 32 个时钟周期翻转一次。`],[`INMP441 SD`,`GPIO 42`,`数据，最高有效位在前。已下拉，所以没接麦克风时读到的全是零。`],[`MAX98357A VIN · GND`,`5V`,`扬声器功放。5V 功率最大（4 Ω 负载约 3 W）；3V3 也能工作，声音小一些。`],[`MAX98357A BCLK`,`GPIO 39`,`第二个 I2S 端口 (I2S1) 的位时钟；麦克风使用 I2S0，所以两者可以同时工作。`],[`MAX98357A LRC`,`GPIO 38`,`字选择（左/右）。`],[`MAX98357A DIN`,`GPIO 47`,`采样数据，16 位。`],[`MAX98357A GAIN · SD`,`不接`,`两个都悬空：增益 9 dB，播放 (左 + 右) / 2。`],[`扬声器 (4 Ω, 3 W)`,`功放 + / −`,`接在功放的螺丝端子上：JST-PH2.0 连接线的两根线，红线接 +。`],[`屏幕（8 根线）`,`同第 03 课`,`保持不变。GPIO 5 上的按钮是可选的：它的作用和 BOOT 一样。`]]},commands:{0:{does:`构建 S6 实验并写入开发板，然后用 <code>uv run pio device monitor</code> 打开监视器。`,see:`<code>Listening for an INMP441 on the I2S pins...</code>、<code>Microphone: INMP441 (I2S, digital) (mic setting: auto)</code>（或 KY-037），然后是 <code>Sound lab S6 …</code>、命令列表，以及扬声器发出的三音问候。安静半秒钟：<code>- learning the quiet...</code>`,fix:`选错了麦克风：<code>mic inmp441</code> 或 <code>mic ky037</code>（会保存并重启）。没有问候音：扬声器是可选的；检查 VIN 和 DIN。“Failed to connect”：按住 BOOT，点按 RST，松开 BOOT，再运行一次。`},1:{does:`接下来的模式会成为秘密（2-12 次敲击；安静 1.5 秒结束）。保存在 NVS 中。`,see:`<code>- knock your new secret, then wait 1.5 s</code>，然后是 <code>+ secret saved: 5 knocks, 1.2 s</code>。`,fix:`<code>a secret needs 2 knocks or more</code>。`},2:{does:`每个完成的模式都会与秘密比较。`,see:`<code>+ OPEN (score 92)</code>：锁梁抬起，GPIO 4 上的 LED 和 RGB LED 绿色亮 5 秒。错误：<code>x locked: the rhythm is off</code>。`,fix:`漏掉了敲击：用力敲，靠近麦克风；<code>knock show</code> 会打印两段节奏。`},3:{does:`把秘密按敲击的精确时间回放成咔哒声（esp_timer 每 2 ms 检查一次）。`,see:`<code>- playing the secret: 5 knocks</code>，以及扬声器发出你的节奏。`,fix:`<code>sound is off: sound on</code>。`},4:{does:`每个间隔最多可以偏离整个模式的 20 %（默认 12）。`,see:`<code>- tolerance 20%</code>。`,fix:``},5:{does:`Clap Bird：新的一局。拍一下手开始；每拍一下就扇一下翅膀。`,see:`<code>clap to fly!</code>；之后是 <code>+ new best: 6</code>。`,fix:`翅膀扇得慢了：敲击式的拍手（短而尖锐）触发起始点最快。`},6:{does:`关闭扬声器上的游戏音效（保存在 NVS 中，命名空间 <code>games</code>）。`,see:`<code>- game sounds off</code>。`,fix:``},7:{does:`每个节拍一声滴答。每次滴答之后开发板约有 200 ms 听不见（回声防护），所以这个窗口内的节拍会被跳过。默认关闭。`,see:`<code>- a tick on every beat (the board can't hear for ~200 ms after it)</code>。`,fix:``},8:{does:`在 <b>party</b> 上，每个节拍都会闪一种颜色、发出一个圆环，并点亮 RGB LED。`,see:`几个节拍之后出现一个 BPM 数字（例如 120）。`,fix:`节拍太多：<code>party sens 2.0</code>。太少：<code>party sens 1.3</code>。`}},panels:{0:{title:`敲击锁的匹配器`,intro:`用按钮（或空格键）敲击。第一个模式成为秘密；之后的模式会逐个间隔地比较，每个间隔都按占整个模式的比例计算，所以速度无关紧要。移动容差。`},1:{title:`屏幕上显示什么`,intro:`三个视图。单击 = 下一个，双击 = 左下角的操作（knock set、bird、party reset），长按 = knock show。在这个预览里，点击屏幕（或按空格键）就是一次拍手：可以玩 Clap Bird。`}},steps:[`接线与 S1 相同。可选：第 02 课的 LED 接在 GPIO 4 上，作为锁的锁舌。`,`烧录 <code>sound-lab-s6</code>。在 <b>knock</b> 上：<code>knock set</code> 并敲一段节奏。<b>检查点 1：</b>秘密已保存。`,`再敲一次，稍微慢一点。<b>检查点 2：</b>OPEN。然后敲一个错的：locked。`,`点按切换到 <b>bird</b> 并拍手。<b>检查点 3：</b>通过 5 根管子。`,`点按切换到 <b>party</b>，播放一首歌。<b>检查点 4：</b>BPM 稳定下来。`],note:`对检测器来说，敲击就是拍手（短促的砰声，这里最长 200 ms）。这把锁比较的是节奏，而不是响度或速度，所以它只是个玩具，不是安全措施：任何听到你敲击的人都能模仿。Clap Bird 以固定的 1/60 秒步长运行物理计算，不管屏幕怎么样，所以在任何帧率下游戏手感都一样；它在起始点（立刻）扇翅膀，而不是在拍手完成时（160 ms 之后）。`},S7:{title:`扬声器`,heading:`让开发板发声：一个用单个扬声器的合成器`,goal:`<span class="snd-parts"><span class="need">MAX98357A + speaker</span></span>数字通过 I2S 送到 <b>MAX98357A</b>，一个 D 类功放：它让扬声器每秒完全接通和断开约 300 000 次，每个脉冲持续多久取决于那个数字。纸盆太慢，跟不上这些脉冲，所以它随平均值运动：也就是波形。S7 能产生五种音色、和弦、包络、曲子和游戏音效，并画出你听到的声音。`,goalLine:`听出五种波形的区别，弹一个和弦和一段曲子，改变包络直到一个音听起来像拨弦，并触发每一种游戏音效。`,goalCheck:[`<code>beep</code> 和开机问候铃声在 <code>vol 20</code> 下从扬声器发出。`,`在 <b>wave</b> 上，频谱对正弦波显示一条线，对方波显示奇次谐波，对锯齿波显示所有谐波。`,`<code>adsr 1 300 0 50</code> 让 <code>note A4 600</code> 听起来像拨弦；<code>adsr 300 80 65 300</code> 则是柔和的。`,`<code>tune korobeiniki</code> 播放，钢琴卷帘滚动；<code>fx explosion</code> 发出隆隆声。`],learn:[`I2S 输出`,`D 类功放`,`音色 = 谐波`,`16 kHz 下的混叠`,`ADSR 与爆音`,`半音与和弦`,`速度`,`程序化声音`,`音量的平方`],pins:{0:{role:`VCC`},1:{role:`MICS +`},2:{role:`AO`},3:{role:`BLK`},4:{role:`RES`},5:{role:`DC`},6:{role:`CS`},7:{role:`SDA`},8:{role:`SCL`},9:{role:`AMP VIN`},10:{role:`GND`},11:{role:`BTN`},12:{role:`MICS G`},13:{role:`SD`},14:{role:`WS`},15:{role:`SCK`},16:{role:`BCLK`},17:{role:`LRC`},18:{role:`BOOT`},19:{role:`DIN`},20:{role:`DO`},21:{role:`AMP G`}},wiring:{title:`接线：麦克风和扬声器（按实验需要接线；屏幕保持与第 03 课相同）`,head:[`模块引脚`,`ESP32-S3`,`说明`],rows:[[`KY-037 + · G`,`3V3`,`模拟麦克风。+ 接第二个 3V3 引脚（屏幕用了第一个），G 接 GND。<b>绝不能接 5 V</b>：AO 和 DO 的电压会摆动到模块的供电电压，而 ESP32-S3 的引脚最高只能承受 3.3 V。`],[`KY-037 AO`,`GPIO 6`,`模拟输出：麦克风的电压。GPIO 6 是 ADC1 通道 5：开启 Wi-Fi 时 ADC1 仍能工作，ADC2 不行。`],[`KY-037 DO`,`GPIO 21`,`数字输出：当声音比蓝色微调电位器的设定值更响时，LM393 比较器输出高电平。`],[`INMP441 VDD · GND`,`3V3`,`数字麦克风 (I2S)。VDD 接 3V3（与 KY-037 共用面包板电源轨），GND 接 GND。只能接 3.3 V。`],[`INMP441 L/R`,`GND`,`低电平 = 它在左声道时隙说话，也就是开发板读取的那一个。`],[`INMP441 SCK`,`GPIO 40`,`位时钟。由 ESP32 驱动：16 000 × 64 = 1.024 MHz。`],[`INMP441 WS`,`GPIO 41`,`字选择：左时隙 / 右时隙，每 32 个时钟周期翻转一次。`],[`INMP441 SD`,`GPIO 42`,`数据，最高有效位在前。已下拉，所以没接麦克风时读到的全是零。`],[`MAX98357A VIN · GND`,`5V`,`扬声器功放。5V 功率最大（4 Ω 负载约 3 W）；3V3 也能工作，声音小一些。`],[`MAX98357A BCLK`,`GPIO 39`,`第二个 I2S 端口 (I2S1) 的位时钟；麦克风使用 I2S0，所以两者可以同时工作。`],[`MAX98357A LRC`,`GPIO 38`,`字选择（左/右）。`],[`MAX98357A DIN`,`GPIO 47`,`采样数据，16 位。`],[`MAX98357A GAIN · SD`,`不接`,`两个都悬空：增益 9 dB，播放 (左 + 右) / 2。`],[`扬声器 (4 Ω, 3 W)`,`功放 + / −`,`接在功放的螺丝端子上：JST-PH2.0 连接线的两根线，红线接 +。`],[`屏幕（8 根线）`,`同第 03 课`,`保持不变。GPIO 5 上的按钮是可选的：它的作用和 BOOT 一样。`]]},commands:{0:{does:`构建 S7 实验并写入开发板，然后用 <code>uv run pio device monitor</code> 打开监视器。`,see:`<code>Listening for an INMP441 on the I2S pins...</code>、<code>Microphone: INMP441 (I2S, digital) (mic setting: auto)</code>（或 KY-037），然后是 <code>Sound lab S7 …</code>、命令列表，以及扬声器发出的三音问候。安静半秒钟：<code>- learning the quiet...</code>`,fix:`选错了麦克风：<code>mic inmp441</code> 或 <code>mic ky037</code>（会保存并重启）。没有问候音：扬声器是可选的；检查 VIN 和 DIN。“Failed to connect”：按住 BOOT，点按 RST，松开 BOOT，再运行一次。`},1:{does:`从小声开始：音量是平方关系，20 = 满功率的 4 %。保存在 NVS 中（默认 40）。`,see:`<code>- volume 20</code>；然后 <code>beep</code> 播放 440 Hz。`,fix:`没有声音：VIN 接 5V，DIN 接 47，BCLK 39，LRC 38；扬声器接在端子上。`},2:{does:`音色：sine、square、triangle、saw、noise（<code>wave next</code>，或在 <b>wave</b> 上双击）。`,see:`<code>- wave square</code>；频谱中的谱线位于音高的 1、3、5…… 倍处。`,fix:``},3:{does:`播放一个音（音名或 Hz）600 ms。在 <b>envelope</b> 上双击效果相同。`,see:`圆点沿着 ADSR 曲线移动。`,fix:`高于 7 kHz 时显示 <code>close to 8 kHz: the limit at 16 kHz</code>。`},4:{does:`包络：起音 (attack) ms、衰减 (decay) ms、保持 (sustain) %、释音 (release) ms（默认 6 80 65 90）。起音为 0 会产生爆音。`,see:`<code>- adsr 1 300 0 50</code>：拨动的琴弦。`,fix:``},5:{does:`在单声部扬声器上同时发多个音：开发板把它们叠加到一个缓冲区里（PSRAM 中 30 秒）。`,see:`<code>- Am = A4 C5 E5</code>；<b>keys</b> 上亮起三个琴键。`,fix:``},6:{does:`按 <code>bpm</code>（默认 120）一个接一个地播放音符：/4 四分音符，/8 八分音符，r 休止符，. 附点。`,see:`琴键依次亮起。`,fix:``},7:{does:`twinkle ode happy korobeiniki scale arpeggio。在 <b>tunes</b> 上双击播放选中的那首；长按选择下一首。`,see:`钢琴卷帘从琥珀色的播放头旁滚过。`,fix:``},8:{does:`用配方生成的游戏音效：扫频、噪声、逐渐关闭的滤波器。`,see:`<b>fx</b> 上显示整个波形，播放头从上面划过。`,fix:``},9:{does:`静音。`,see:`标题栏里的波纹停止。`,fix:``}},panels:{0:{title:`从数字到振动的纸盆`,intro:`一个采样被开发板算出来之后会发生什么，为什么音量旋钮是平方关系，以及让麦克风不把扬声器的声音当成拍手的回声防护。`},1:{title:`一个可以玩的合成器`,intro:`与开发板相同的波形和包络。选一种波形，按一个键在这个浏览器里听它（声音很小；不按键就不会有声音），并拖动包络的手柄。红色的柱子是开发板在 16 kHz 下产生不了的谐波：它们会折叠回来，变成错误的音。`},2:{title:`屏幕上显示什么`,intro:`五个视图。单击 = 下一个，双击 = 左下角的操作。keys：长按 = 下一个和弦。tunes 和 fx：长按选择下一个。在其他视图上，长按会停止声音。`}},steps:[`接上 MAX98357A：VIN → 5V，GND，BCLK → 39，LRC → 38，DIN → 47；扬声器接在它的螺丝端子上（红线接 +）。GAIN 和 SD 保持悬空。不需要麦克风。`,`烧录 <code>sound-lab-s7</code>。<b>检查点 1：</b>开机问候铃声和 <code>start quiet: vol 20, then raise it</code>。`,`<code>vol 20</code>，然后配合 <code>note A4</code> 执行五次 <code>wave next</code>。<b>检查点 2：</b>五种音色，五种频谱。`,`<code>adsr 1 300 0 50</code>、<code>note A4 600</code>；然后 <code>adsr 0 0 100 0</code>。<b>检查点 3：</b>你听到了包络消除掉的爆音。`,`<code>chord Am</code>、<code>tune ode</code>、<code>fx coin</code>。<b>检查点 4：</b>三个都能播放。`],note:`一个扬声器，一路数据流：和弦和曲子会先渲染到 PSRAM（最长 30 秒），然后再播放。在每秒 16 000 个采样时，8 kHz 以上的内容不存在，所以方波或锯齿波的高次谐波会折叠回来变成错误的频率：高音带一点沙沙声，这是简单合成器的真实局限。其他每个声音实验都用同一个扬声器播放它们的提示音，回声防护会在它播放时让检测器“充耳不闻”。`},S8:{title:`语音特效`,heading:`一只会复述你的话的鹦鹉，和一个实时机器人声音`,goal:`<span class="snd-parts"><span class="need">INMP441</span><span class="need">MAX98357A + speaker</span></span>麦克风输入，扬声器输出。你说点什么，鹦鹉就会学给你听：正常、<b>花栗鼠</b>（快 1.5 倍）、<b>巨人</b>（0.7 倍）、<b>机器人</b>（环形调制 + 6 位粗糙化）、带<b>回声</b>，或者<b>倒放</b>。然后是实时特效：一个你对着说话的回声，一个机器人声音。鹦鹉像 S4 一样由声音触发（12 dB，0.3 秒预录音，0.7 秒保持，最长 6 秒），并且永远听不到自己。`,goalLine:`让鹦鹉用三种声音复述你的话，通过实时回声说话而不啸叫，并解释为什么花栗鼠说话很快。`,goalCheck:[`你说了一个词，鹦鹉用花栗鼠的声音回答；<code>fx giant</code> + <code>again</code> 则用低沉缓慢的声音回答。`,`<b>echo</b> 视图：<code>echo on</code>，一下拍手会以逐渐减弱的重复声回来，延迟约 60-80 ms。`,`你把扬声器对着麦克风，引发了（并由防护制止了）一次啸叫：<code>Howl! Move the speaker away or turn it down</code>。`],learn:[`重采样 = 音高 + 速度`,`环形调制 f±c`,`位粗糙化 (bitcrush)`,`延迟 + 反馈`,`环路增益 < 1`,`啸叫检测`,`延迟预算`,`回声防护`],pins:{0:{role:`VCC`},1:{role:`MICS +`},2:{role:`AO`},3:{role:`BLK`},4:{role:`RES`},5:{role:`DC`},6:{role:`CS`},7:{role:`SDA`},8:{role:`SCL`},9:{role:`AMP VIN`},10:{role:`GND`},11:{role:`BTN`},12:{role:`MICS G`},13:{role:`SD`},14:{role:`WS`},15:{role:`SCK`},16:{role:`BCLK`},17:{role:`LRC`},18:{role:`BOOT`},19:{role:`DIN`},20:{role:`DO`},21:{role:`AMP G`}},wiring:{title:`接线：麦克风和扬声器（按实验需要接线；屏幕保持与第 03 课相同）`,head:[`模块引脚`,`ESP32-S3`,`说明`],rows:[[`KY-037 + · G`,`3V3`,`模拟麦克风。+ 接第二个 3V3 引脚（屏幕用了第一个），G 接 GND。<b>绝不能接 5 V</b>：AO 和 DO 的电压会摆动到模块的供电电压，而 ESP32-S3 的引脚最高只能承受 3.3 V。`],[`KY-037 AO`,`GPIO 6`,`模拟输出：麦克风的电压。GPIO 6 是 ADC1 通道 5：开启 Wi-Fi 时 ADC1 仍能工作，ADC2 不行。`],[`KY-037 DO`,`GPIO 21`,`数字输出：当声音比蓝色微调电位器的设定值更响时，LM393 比较器输出高电平。`],[`INMP441 VDD · GND`,`3V3`,`数字麦克风 (I2S)。VDD 接 3V3（与 KY-037 共用面包板电源轨），GND 接 GND。只能接 3.3 V。`],[`INMP441 L/R`,`GND`,`低电平 = 它在左声道时隙说话，也就是开发板读取的那一个。`],[`INMP441 SCK`,`GPIO 40`,`位时钟。由 ESP32 驱动：16 000 × 64 = 1.024 MHz。`],[`INMP441 WS`,`GPIO 41`,`字选择：左时隙 / 右时隙，每 32 个时钟周期翻转一次。`],[`INMP441 SD`,`GPIO 42`,`数据，最高有效位在前。已下拉，所以没接麦克风时读到的全是零。`],[`MAX98357A VIN · GND`,`5V`,`扬声器功放。5V 功率最大（4 Ω 负载约 3 W）；3V3 也能工作，声音小一些。`],[`MAX98357A BCLK`,`GPIO 39`,`第二个 I2S 端口 (I2S1) 的位时钟；麦克风使用 I2S0，所以两者可以同时工作。`],[`MAX98357A LRC`,`GPIO 38`,`字选择（左/右）。`],[`MAX98357A DIN`,`GPIO 47`,`采样数据，16 位。`],[`MAX98357A GAIN · SD`,`不接`,`两个都悬空：增益 9 dB，播放 (左 + 右) / 2。`],[`扬声器 (4 Ω, 3 W)`,`功放 + / −`,`接在功放的螺丝端子上：JST-PH2.0 连接线的两根线，红线接 +。`],[`屏幕（8 根线）`,`同第 03 课`,`保持不变。GPIO 5 上的按钮是可选的：它的作用和 BOOT 一样。`]]},commands:{0:{does:`构建 S8 实验并写入开发板，然后用 <code>uv run pio device monitor</code> 打开监视器。`,see:`<code>Listening for an INMP441 on the I2S pins...</code>、<code>Microphone: INMP441 (I2S, digital) (mic setting: auto)</code>（或 KY-037），然后是 <code>Sound lab S8 …</code>、命令列表，以及扬声器发出的三音问候。安静半秒钟：<code>- learning the quiet...</code>`,fix:`选错了麦克风：<code>mic inmp441</code> 或 <code>mic ky037</code>（会保存并重启）。没有问候音：扬声器是可选的；检查 VIN 和 DIN。“Failed to connect”：按住 BOOT，点按 RST，松开 BOOT，再运行一次。`},1:{does:`保持低音量：麦克风会听到扬声器。`,see:`<code>- volume 25</code>。`,fix:`使用 KY-037 时：<code>KY-037: it works, but an INMP441 sounds much clearer</code>。`},2:{does:`比安静电平高出 12 dB 就会开始一段录音，包含之前的 0.3 秒；安静 0.7 秒结束；然后通过所选的声音播放回来。`,see:`气泡：<code>I'm listening...</code>，REC，然后是 <code>Squawk!</code>，鸟嘴在动；<code>+ chipmunk, 1.4 s, x9 louder</code>。`,fix:`<code>too short: a bang, not a word</code>：多说一会儿。一直不启动：<code>trigger 8</code>。`},3:{does:`鹦鹉的声音：normal chipmunk giant robot echo reverse。在 <b>parrot</b> 上双击。`,see:`<code>- voice: robot (ring modulator + bitcrush)</code>。`,fix:``},4:{does:`用当前的声音再说一遍最后一段录音（在 <b>scope</b> 上双击）。`,see:`同样的话，另一种声音。`,fix:`<code>nothing recorded yet: say something first</code>。`},5:{does:`实时：麦克风 → 延迟线 → 扬声器。<code>delay 120</code>（20-500 ms），<code>feedback 60</code>（0-70 %）。需要麦克风工作在 16 000 Hz。`,see:`<code>! live echo: speaker away from the mic, volume low</code>；<b>echo</b> 视图上一下拍手的各次回声，延迟约 60-80 ms。`,fix:`啸叫：防护会用低沉的 No 把它制止。把扬声器转开，调低 <code>vol</code> 或 <code>feedback</code>。`},6:{does:`实时：你的声音 × 一个缓慢的正弦波（<code>carrier 50</code>，10-300 Hz）+ 粗糙化。每个频率 f 变成 f − c 和 f + c。`,see:`机器人的嘴随着输出的声音亮起。<code>carrier 200</code> 听起来像铃声。`,fix:``}},panels:{0:{title:`浏览器里的鹦鹉`,intro:`与 fx.h 相同的特效，在这个页面里。已加载一个示例声音；录制你自己的声音是可选的，只有在你按下按钮时才会开始（3 秒，录音时有红色指示，没有任何内容会离开这个页面）。`},1:{title:`屏幕上显示什么`,intro:`四个视图。单击 = 下一个，双击 = 左下角的操作（fx next、echo、robot、again），长按 = 手动录音 / 停止。`}},steps:[`接上 INMP441（VDD 3V3，GND，L/R → GND，SCK 40，WS 41，SD 42），并像 S7 一样接上 MAX98357A + 扬声器。让扬声器背向麦克风。`,`烧录 <code>sound-lab-s8</code>，<code>vol 25</code>。<b>检查点 1：</b><code>Microphone: INMP441</code>，鹦鹉说 “Say something!”。`,`说一小句话。<b>检查点 2：</b>花栗鼠回答了。`,`<code>fx giant</code>，<code>again</code>；<code>fx reverse</code>，<code>again</code>。<b>检查点 3：</b>你能说出为什么巨人说话慢。`,`<code>echo on</code>，拍手。<b>检查点 4：</b>逐渐减弱的重复声；<code>echo off</code>。`,`<code>robot on</code>，说话。<b>检查点 5：</b>机器人声音；<code>robot off</code>。`],note:`改变录音的速度会同时改变它的音高和长度：这就是花栗鼠说话快的原因。要在保持速度的同时改变音高，需要复杂得多的 DSP（颗粒或相位声码器）。反馈：如果麦克风听到的声音回来时比出去时更响（环路增益大于 1），它就会一圈圈地循环：这就是啸叫。当电平持续上升（300 ms 内上升 9 dB）或保持在 −12 dBFS 以上时，防护会切断实时特效。延迟 = 一帧屏幕处理时间 + 扬声器的队列 + 它 16 ms 的 DMA 块。`}};export{e as default};
